var C = ARISTO.colors;
var canvas = document.getElementById('plot');
var readout = document.getElementById('readout');
var flip1Btn = document.getElementById('flip1');
var flip50Btn = document.getElementById('flip50');
var resetBtn = document.getElementById('reset');

var heads = 0;
var total = 0;
var history = []; // running percentage after each flip (sampled, capped)

function flipOnce() {
  total++;
  if (Math.random() < 0.5) heads++;
  var pct = (heads / total) * 100;
  history.push(pct);
  // cap stored points so chart stays fast; keep every point up to 2000, else thin
  if (history.length > 2000) {
    var thinned = [];
    for (var i = 0; i < history.length; i += 2) thinned.push(history[i]);
    history = thinned;
  }
}

function doFlips(n) {
  for (var i = 0; i < n; i++) flipOnce();
  update();
}

function fmtPct(n) {
  return (Math.round(n * 10) / 10).toString();
}

var plot = ARISTO.canvas(canvas, function (ctx, w, h) {
  var padL = 36, padR = 10, padT = 12, padB = 22;
  var plotW = w - padL - padR;
  var plotH = h - padT - padB;

  // background grid lines (0,25,50,75,100)
  ctx.lineWidth = 1;
  ctx.strokeStyle = C.line;
  ctx.fillStyle = C.muted;
  ctx.font = '12px system-ui, sans-serif';
  ctx.textAlign = 'right';
  ctx.textBaseline = 'middle';
  var marks = [0, 25, 50, 75, 100];
  marks.forEach(function (m) {
    var y = padT + plotH * (1 - m / 100);
    ctx.beginPath();
    ctx.moveTo(padL, y);
    ctx.lineTo(w - padR, y);
    ctx.stroke();
    ctx.fillText(String(m), padL - 6, y);
  });

  // axes
  ctx.strokeStyle = C.muted;
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.moveTo(padL, padT);
  ctx.lineTo(padL, padT + plotH);
  ctx.lineTo(w - padR, padT + plotH);
  ctx.stroke();

  // dashed 50% theoretical line
  var y50 = padT + plotH * 0.5;
  ctx.setLineDash([6, 4]);
  ctx.strokeStyle = C.warning;
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(padL, y50);
  ctx.lineTo(w - padR, y50);
  ctx.stroke();
  ctx.setLineDash([]);
  ctx.fillStyle = C.warning;
  ctx.textAlign = 'left';
  ctx.fillText('50% theoretical', padL + 6, y50 - 10);

  // data line
  if (history.length > 0) {
    ctx.strokeStyle = C.accentText;
    ctx.lineWidth = 2.5;
    ctx.lineJoin = 'round';
    ctx.beginPath();
    var n = history.length;
    for (var i = 0; i < n; i++) {
      var x = padL + (n === 1 ? plotW : (plotW * i) / (n - 1));
      var val = history[i];
      var y = padT + plotH * (1 - val / 100);
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // dot at last point
    var lastX = padL + plotW;
    var lastY = padT + plotH * (1 - history[n - 1] / 100);
    ctx.fillStyle = C.accentText;
    ctx.beginPath();
    ctx.arc(lastX, lastY, 4, 0, Math.PI * 2);
    ctx.fill();
  } else {
    ctx.fillStyle = C.muted;
    ctx.textAlign = 'center';
    ctx.font = '13px system-ui, sans-serif';
    ctx.fillText('Flip the coin to begin', padL + plotW / 2, padT + plotH / 2);
  }

  // x axis label
  ctx.fillStyle = C.muted;
  ctx.textAlign = 'center';
  ctx.font = '12px system-ui, sans-serif';
  ctx.fillText('flips so far: ' + total, padL + plotW / 2, padT + plotH + 16);
}, 0.55);

function update() {
  if (total === 0) {
    readout.textContent = '0 flips — no data yet';
  } else {
    var pct = fmtPct((heads / total) * 100);
    readout.textContent = total + ' flip' + (total === 1 ? '' : 's') + ' — ' + heads + ' heads — ' + pct + '% heads';
  }
  plot.redraw();
}

flip1Btn.addEventListener('click', function () { doFlips(1); });
flip50Btn.addEventListener('click', function () { doFlips(50); });
resetBtn.addEventListener('click', function () {
  heads = 0;
  total = 0;
  history = [];
  update();
});

update();
